    (3::smallint, 'multiple_choice', 'Bình ăn kẹo và uống nước ngọt mỗi ngày nhưng ít đánh răng. Điều gì dễ xảy ra với Bình?', 'Bình dễ bị sâu răng', 'Răng Bình sẽ chắc khỏe hơn', 'Bình sẽ cao lớn nhanh hơn', null, 'Bình dễ bị sâu răng', null::jsonb, 'Đường bám lâu trên răng là thức ăn cho vi khuẩn gây sâu răng.', 'han_che_do_ngot'),
    (3::smallint, 'multiple_choice', 'Món nào là bữa phụ lành mạnh nhất cho em?', 'Một hộp sữa và một quả chuối', 'Một gói khoai tây chiên', 'Một cốc nước ngọt có ga', 'Một túi kẹo', 'Một hộp sữa và một quả chuối', null::jsonb, 'Sữa cho chất đạm và canxi, chuối cho vitamin. Các món còn lại nhiều đường hoặc dầu mỡ.', 'bua_phu')
