    (2::smallint, 'multiple_choice', 'Khi ngồi sau xe máy, em nên để chân ở đâu?', 'Trên chỗ để chân, tránh xa bánh xe', 'Thả lủng lẳng xuống đường', 'Gác lên yên xe', null, 'Trên chỗ để chân, tránh xa bánh xe', null::jsonb, 'Để chân đúng chỗ giúp chân em không bị cuốn vào bánh xe hay chạm ống xả nóng.', 'ngoi_xe_may'),
    (2::smallint, 'multiple_choice', 'Khi phải đứng trên xe buýt đang chạy, em nên làm gì?', 'Bám chắc vào tay vịn', 'Buông tay đứng giữa xe', 'Chạy đi chạy lại trong xe', null, 'Bám chắc vào tay vịn', null::jsonb, 'Bám tay vịn giúp em không bị ngã khi xe phanh hoặc rẽ.', 'xe_buyt'),
    (3::smallint, 'multiple_choice', 'Bố chở An ra chợ gần nhà. An nói: “Gần thôi, không cần đội mũ bảo hiểm.” Em thấy thế nào?', 'An nói sai, đi gần cũng phải đội mũ bảo hiểm', 'An nói đúng vì đường gần', 'An chỉ cần đội mũ khi trời nắng', null, 'An nói sai, đi gần cũng phải đội mũ bảo hiểm', null::jsonb, 'Va chạm có thể xảy ra ở bất cứ đâu, kể cả quãng đường ngắn.', 'mu_bao_hiem'),
    (3::smallint, 'multiple_choice', 'Việc nào KHÔNG nên làm khi đi xe buýt?', 'Ăn quà rồi vứt vỏ ra sàn xe', 'Bám tay vịn khi đứng', 'Nhường ghế cho người già', 'Nói chuyện nhỏ nhẹ', 'Ăn quà rồi vứt vỏ ra sàn xe', null::jsonb, 'Vứt rác ra sàn làm bẩn xe và có thể làm người khác trượt ngã.', 'xe_buyt'),
    (3::smallint, 'multiple_choice', 'Ô tô dừng sát vỉa hè để Mai xuống. Thứ tự nào đúng?', 'Chờ xe dừng hẳn, tháo dây an toàn, mở cửa phía vỉa hè rồi xuống', 'Mở cửa phía lòng đường rồi nhảy xuống', 'Tháo dây an toàn và mở cửa khi xe còn đang chạy', null, 'Chờ xe dừng hẳn, tháo dây an toàn, mở cửa phía vỉa hè rồi xuống', null::jsonb, 'Xe dừng hẳn mới tháo dây và xuống, mở cửa phía vỉa hè để tránh xe đang chạy.', 'len_xuong_xe'),
    (3::smallint, 'multiple_choice', 'Nam ra cổng trường thì thấy một xe tải lớn đang lùi ở gần. Nam nên làm gì?', 'Tránh xa phía sau và hai bên xe tải', 'Đứng sát sau xe để xem', 'Chạy vòng qua sát đầu xe', null, 'Tránh xa phía sau và hai bên xe tải', null::jsonb, 'Người lái xe tải khó thấy em ở phía sau và sát hai bên xe, nên em cần đứng thật xa.', 'diem_mu'),
    (3::smallint, 'multiple_choice', 'Minh lên xe buýt, thấy còn một ghế trống. Lúc đó một bà cụ cũng vừa lên xe. Minh nên làm gì?', 'Mời bà cụ ngồi ghế đó', 'Chạy nhanh đến ngồi trước', 'Đặt cặp lên ghế để giữ chỗ', null, 'Mời bà cụ ngồi ghế đó', null::jsonb, 'Nhường ghế cho người già là việc làm lịch sự, giúp bà không bị ngã khi xe chạy.', 'xe_buyt'),
    (3::smallint, 'multiple_choice', 'Lan vừa xuống xe buýt và muốn sang bên kia đường. Lan nên làm gì?', 'Chờ xe buýt đi khỏi, quan sát kĩ rồi mới qua đường', 'Đi vòng ngay trước đầu xe buýt', 'Chạy vòng sau đuôi xe buýt cho nhanh', null, 'Chờ xe buýt đi khỏi, quan sát kĩ rồi mới qua đường', null::jsonb, 'Xe buýt to che khuất tầm nhìn, người lái các xe khác khó thấy Lan.', 'len_xuong_xe'),
    (3::smallint, 'multiple_choice', 'Việc nào KHÔNG an toàn khi đi xe máy cùng bố mẹ?', 'Đứng lên yên xe khi xe đang chạy', 'Đội mũ bảo hiểm và cài quai', 'Ngồi sau, bám chắc người lái', 'Để chân trên chỗ để chân', 'Đứng lên yên xe khi xe đang chạy', null::jsonb, 'Đứng trên xe đang chạy rất dễ bị ngã. Em cần ngồi yên và bám chắc.', 'ngoi_xe_may')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
 where l.week_number = 5 and l.lesson_order = 5
   and not exists (select 1 from public.questions q where q.lesson_id = l.id and q.generator_type = 'ky_nang_song');

-- Kỹ năng sống • Bài 6: Phòng tránh đuối nước (25 câu)
insert into public.lessons (subject_id, week_number, lesson_order, name, description, is_published, publish_mode)
select id, 6, 6, 'Phòng tránh đuối nước', 'Học Vui — Kỹ năng sống, bài 6', true, 'week' from public.subjects where code = 'ky_nang_song'
on conflict (subject_id, week_number, lesson_order) do nothing;

insert into public.questions (lesson_id, difficulty, question_type, question_text, option_a, option_b, option_c, option_d,
                              correct_answer, accepted_answers, explanation, skill_tag, source_book, generator_type)
