    (2::smallint, 'multiple_choice', 'Vì sao em không nên bơi ngay khi vừa ăn no?', 'Vì dễ bị đau bụng, chuột rút', 'Vì nước sẽ bị bẩn', 'Vì sẽ bơi nhanh quá', 'Vì áo phao bị chật', 'Vì dễ bị đau bụng, chuột rút', null::jsonb, 'Vừa ăn no mà bơi dễ bị đau bụng, chuột rút, rất nguy hiểm khi đang ở dưới nước.', 'an_no'),
    (2::smallint, 'multiple_choice', 'Vì sao bờ ao, bờ sông là nơi nguy hiểm để chơi đùa?', 'Vì bờ thường trơn, dễ trượt ngã xuống nước', 'Vì ở đó có nhiều cây xanh', 'Vì ở đó gió thổi mát', 'Vì ở đó có nhiều bạn chơi', 'Vì bờ thường trơn, dễ trượt ngã xuống nước', null::jsonb, 'Đất ở bờ ao, bờ sông thường ẩm ướt, trơn trượt nên rất dễ ngã xuống nước.', 'bo_ao_tron'),
