    (2::smallint, 'multiple_choice', 'Thấy bạn rơi xuống nước gần bờ, em có thể đưa cho bạn vật gì để bám?', 'Cây sào dài hoặc chiếc phao', 'Hòn đá to', 'Chiếc túi ni lông nhỏ', 'Chiếc giày', 'Cây sào dài hoặc chiếc phao', null::jsonb, 'Phao giúp bạn nổi, cây sào dài giúp bạn bám vào mà em vẫn đứng an toàn trên bờ.', 'nem_phao'),
    (2::smallint, 'multiple_choice', 'Vì sao trẻ em nên học bơi?', 'Để biết cách giữ an toàn khi ở dưới nước', 'Để được ra sông chơi một mình', 'Để không cần mặc áo phao nữa', 'Để thi bơi với người lớn', 'Để biết cách giữ an toàn khi ở dưới nước', null::jsonb, 'Biết bơi giúp em tự bảo vệ mình tốt hơn, nhưng vẫn luôn cần người lớn trông chừng.', 'hoc_boi'),
    (2::smallint, 'multiple_choice', 'Bạn Hoa đã biết bơi. Khi đi thuyền, Hoa có cần mặc áo phao không?', 'Có, ai đi thuyền cũng cần mặc áo phao', 'Không, vì Hoa đã biết bơi', 'Chỉ mặc khi trời mưa', null, 'Có, ai đi thuyền cũng cần mặc áo phao', null::jsonb, 'Dù biết bơi, khi ngã xuống sông vẫn có thể bị mệt hoặc hoảng sợ. Áo phao giữ em an toàn.', 'ao_phao'),
    (2::smallint, 'multiple_choice', 'Khi đi tắm biển cùng gia đình, em nên tắm ở đâu?', 'Khu vực có cờ báo an toàn và người cứu hộ', 'Chỗ vắng người, xa bờ', 'Chỗ sóng to nhất', 'Gần những tảng đá trơn', 'Khu vực có cờ báo an toàn và người cứu hộ', null::jsonb, 'Khu vực có cứu hộ được trông coi cẩn thận, nếu có chuyện sẽ được giúp ngay.', 'tam_bien'),
