    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng khi em đi bơi ở bể?', 'Khởi động – xuống nước khi có người lớn trông – lên bờ nghỉ khi mệt', 'Xuống nước ngay – khởi động – bơi đến khi kiệt sức', 'Ăn thật no – nhảy xuống nước – khởi động sau', null, 'Khởi động – xuống nước khi có người lớn trông – lên bờ nghỉ khi mệt', null::jsonb, 'Khởi động trước, chỉ bơi khi có người lớn trông và nghỉ ngay khi mệt là cách bơi an toàn.', 'thu_tu_boi'),
    (3::smallint, 'multiple_choice', 'Trời mưa lũ, nước ngập tràn qua đường. Bé Na đi học về nên làm gì?', 'Đứng chờ ở chỗ cao và nhờ người lớn đưa qua', 'Tự lội qua cho nhanh', 'Đạp xe băng qua', 'Chạy theo dòng nước để chơi', 'Đứng chờ ở chỗ cao và nhờ người lớn đưa qua', null::jsonb, 'Nước ngập có thể chảy mạnh và che mất hố sâu. Na nên chờ ở chỗ cao và nhờ người lớn giúp.', 'nuoc_ngap_duong'),
