    (3::smallint, 'multiple_choice', 'Bạn Khoa nói: "Tớ biết bơi rồi nên ra sông bơi một mình cũng được." Em thấy thế nào?', 'Chưa đúng, dù biết bơi vẫn cần người lớn trông', 'Đúng, biết bơi thì không sao', 'Đúng, nếu sông vắng người', null, 'Chưa đúng, dù biết bơi vẫn cần người lớn trông', null::jsonb, 'Sông có dòng chảy mạnh và chỗ sâu bất ngờ. Dù biết bơi, trẻ em vẫn cần người lớn trông chừng.', 'biet_boi_van_can_nguoi_lon')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
