-- Kỹ năng sống • Bài 7: An toàn với điện, lửa và gas (25 câu)
insert into public.lessons (subject_id, week_number, lesson_order, name, description, is_published, publish_mode)
select id, 7, 7, 'An toàn với điện, lửa và gas', 'Học Vui — Kỹ năng sống, bài 7', true, 'week' from public.subjects where code = 'ky_nang_song'
on conflict (subject_id, week_number, lesson_order) do nothing;

insert into public.questions (lesson_id, difficulty, question_type, question_text, option_a, option_b, option_c, option_d,
                              correct_answer, accepted_answers, explanation, skill_tag, source_book, generator_type)
select l.id, v.difficulty, v.question_type, v.question_text, v.option_a, v.option_b, v.option_c, v.option_d,
       v.correct_answer, v.accepted_answers, v.explanation, v.skill_tag, 'Học Vui — Kỹ năng sống', 'ky_nang_song'
  from public.lessons l
  join public.subjects s on s.id = l.subject_id and s.code = 'ky_nang_song'
  cross join (values
    (1::smallint, 'multiple_choice', 'Em có được cho ngón tay hoặc vật bằng kim loại vào ổ điện không?', 'Không, vì có thể bị điện giật', 'Có, nếu chỉ chạm nhẹ', 'Có, khi có bạn đứng cạnh', null, 'Không, vì có thể bị điện giật', null::jsonb, 'Trong ổ điện có dòng điện, chọc tay hay vật kim loại vào sẽ bị điện giật rất nguy hiểm.', 'o_dien'),
    (1::smallint, 'multiple_choice', 'Thấy chiếc bật lửa rơi trên sàn nhà, em nên làm gì?', 'Đưa cho người lớn cất đi', 'Bật thử xem có lửa không', 'Mang đi chơi với bạn', 'Giấu vào cặp sách', 'Đưa cho người lớn cất đi', null::jsonb, 'Bật lửa không phải đồ chơi. Đưa cho người lớn cất giúp mọi người tránh bị bỏng, cháy.', 'bat_lua'),
    (1::smallint, 'multiple_choice', 'Muốn bật quạt hay ti vi mà chưa biết cách, em nên làm gì?', 'Nhờ người lớn giúp', 'Tự tháo phích cắm ra xem', 'Dùng kéo cắt thử dây điện', 'Cắm thử thật nhiều lần', 'Nhờ người lớn giúp', null::jsonb, 'Đồ điện cần dùng đúng cách. Khi chưa biết, nhờ người lớn giúp là an toàn nhất.', 'nho_nguoi_lon_dien'),
    (1::smallint, 'multiple_choice', 'Em nên thả diều ở đâu?', 'Bãi đất trống, xa đường dây điện', 'Gần cột điện cao', 'Trên mái nhà', 'Cạnh trạm biến áp', 'Bãi đất trống, xa đường dây điện', null::jsonb, 'Diều vướng vào dây điện có thể làm em bị điện giật. Bãi đất trống xa dây điện là an toàn.', 'tha_dieu'),
    (1::smallint, 'multiple_choice', 'Thấy dây điện bị đứt, hở lõi rơi xuống đất, em nên làm gì?', 'Tránh xa và báo người lớn', 'Nhặt lên cất đi', 'Dùng que sắt khều ra', 'Bước qua cho nhanh', 'Tránh xa và báo người lớn', null::jsonb, 'Dây điện hở có thể làm điện giật. Em tránh xa và báo người lớn để gọi thợ sửa.', 'day_dien_ho'),
    (1::smallint, 'text', 'Điền từ còn thiếu: Khi quần áo bị bén lửa, hãy nhớ: Dừng lại – Nằm xuống – ___.', null, null, null, null, 'lăn', '["lăn tròn","lăn qua lăn lại"]'::jsonb, 'Nằm xuống và lăn giúp dập tắt ngọn lửa trên quần áo.', 'dung_nam_lan'),
    (1::smallint, 'multiple_choice', 'Bình chữa cháy dùng để làm gì?', 'Dập lửa khi đám cháy mới bắt đầu', 'Tưới cây', 'Đựng nước uống', 'Làm đồ chơi', 'Dập lửa khi đám cháy mới bắt đầu', null::jsonb, 'Bình chữa cháy giúp người lớn dập lửa nhỏ. Em không nghịch bình chữa cháy.', 'binh_chua_chay'),
    (1::smallint, 'multiple_choice', 'Em có được tự bật bếp gas để nấu ăn không?', 'Không, chỉ người lớn mới dùng bếp gas', 'Có, khi em đói bụng', 'Có, khi bố mẹ vắng nhà', null, 'Không, chỉ người lớn mới dùng bếp gas', null::jsonb, 'Bếp gas có lửa và khí gas dễ cháy, chỉ người lớn mới được sử dụng.', 'bep_gas'),
    (1::smallint, 'multiple_choice', 'Thấy trạm biến áp có biển báo nguy hiểm, em nên làm gì?', 'Tránh xa, không lại gần', 'Trèo lên xem', 'Ném đồ chơi vào', 'Đứng dựa lưng vào nghỉ', 'Tránh xa, không lại gần', null::jsonb, 'Trạm biến áp có dòng điện rất mạnh, em phải tránh xa.', 'tram_bien_ap'),
    (1::smallint, 'multiple_choice', 'Khi có cháy, em có nên quay lại lấy đồ chơi, cặp sách không?', 'Không, phải thoát ra ngoài ngay', 'Có, nếu là đồ chơi yêu thích', 'Có, nếu em chạy thật nhanh', null, 'Không, phải thoát ra ngoài ngay', null::jsonb, 'Đồ vật có thể mua lại, còn em thì quý nhất. Hãy thoát ra ngoài ngay.', 'khong_quay_lai'),
    (2::smallint, 'multiple_choice', 'Vì sao khi có cháy, em nên cúi thấp hoặc bò sát sàn để thoát ra?', 'Vì khói bốc lên cao, gần sàn ít khói hơn', 'Vì bò thì nhanh hơn chạy', 'Vì để tìm đồ bị rơi', 'Vì để không ai nhìn thấy', 'Vì khói bốc lên cao, gần sàn ít khói hơn', null::jsonb, 'Khói nóng bốc lên cao, sát sàn nhà ít khói nên em dễ thở hơn.', 'thoat_chay'),
    (2::smallint, 'multiple_choice', 'Khi thoát khỏi đám cháy, vì sao nên che mũi miệng bằng khăn ướt?', 'Để bớt hít phải khói', 'Để lau mồ hôi', 'Để không ai nhận ra em', 'Để giữ ấm', 'Để bớt hít phải khói', null::jsonb, 'Khăn ướt giúp cản bớt khói, em đỡ bị ho và khó thở.', 'khan_uot'),
    (2::smallint, 'multiple_choice', 'Khi rút phích cắm ra khỏi ổ điện, cách nào đúng?', 'Tay khô, cầm vào phần nhựa của phích cắm', 'Kéo mạnh vào dây điện', 'Tay ướt, rút thật nhanh', null, 'Tay khô, cầm vào phần nhựa của phích cắm', null::jsonb, 'Tay khô và cầm vào phần nhựa giúp không bị điện giật, dây điện cũng không bị đứt.', 'rut_phich'),
    (2::smallint, 'multiple_choice', 'Vì sao khi ngửi thấy mùi gas, không được bật công tắc điện?', 'Vì tia lửa điện nhỏ có thể làm gas bắt lửa', 'Vì bóng đèn sẽ bị hỏng', 'Vì sẽ tốn tiền điện', 'Vì công tắc bị bẩn', 'Vì tia lửa điện nhỏ có thể làm gas bắt lửa', null::jsonb, 'Khi bật tắt công tắc có thể sinh ra tia lửa rất nhỏ, đủ làm khí gas bốc cháy.', 'mui_gas'),
    (2::smallint, 'multiple_choice', 'Vì sao không được chạm vào đồ điện khi tay đang ướt?', 'Vì nước dẫn điện, dễ bị điện giật', 'Vì đồ điện sẽ bị bẩn', 'Vì tay sẽ bị lạnh', 'Vì đồ điện sẽ bị trơn', 'Vì nước dẫn điện, dễ bị điện giật', null::jsonb, 'Nước dẫn điện, tay ướt chạm đồ điện rất dễ bị giật. Hãy lau khô tay trước.', 'tay_uot'),
    (2::smallint, 'multiple_choice', 'Chiếc diều của em bị mắc trên dây điện. Em nên làm gì?', 'Để yên và nhờ người lớn báo thợ điện', 'Trèo lên cột điện gỡ', 'Dùng sào tre khều xuống', 'Giật thật mạnh dây diều', 'Để yên và nhờ người lớn báo thợ điện', null::jsonb, 'Chạm vào diều hay dây đang mắc trên dây điện có thể bị điện giật. Hãy nhờ người lớn.', 'dieu_mac_day_dien'),
    (2::smallint, 'number', 'Khi có cháy, người lớn gọi số điện thoại ___ để báo cứu hoả.', null, null, null, null, '114', null::jsonb, '114 là số gọi lực lượng cứu hoả, cứu nạn, cứu hộ.', 'so_114'),
    (2::smallint, 'multiple_choice', 'Vì sao em không được nghịch nến, diêm, bật lửa?', 'Vì dễ gây bỏng và cháy nhà', 'Vì sẽ làm hết diêm', 'Vì nến rất đắt', 'Vì bật lửa rất nặng', 'Vì dễ gây bỏng và cháy nhà', null::jsonb, 'Lửa nhỏ có thể bùng to rất nhanh, gây bỏng và cháy nhà.', 'diem_bat_lua'),
    (3::smallint, 'multiple_choice', 'Bạn An đang ở tầng 5 của toà nhà thì nghe chuông báo cháy. An nên đi xuống bằng cách nào?', 'Đi theo lối thoát hiểm, xuống cầu thang bộ', 'Đi thang máy cho nhanh', 'Vào phòng đóng cửa trốn', 'Đứng chờ ở hành lang', 'Đi theo lối thoát hiểm, xuống cầu thang bộ', null::jsonb, 'Khi cháy, thang máy có thể mất điện và kẹt lại. Cầu thang bộ theo lối thoát hiểm là an toàn nhất.', 'thang_may'),
    (3::smallint, 'multiple_choice', 'Việc nào KHÔNG nên làm khi có cháy?', 'Trốn vào gầm giường hoặc trong tủ', 'Cúi thấp người đi ra ngoài', 'Che mũi miệng bằng khăn ướt', 'Đi theo lối thoát hiểm', 'Trốn vào gầm giường hoặc trong tủ', null::jsonb, 'Trốn trong tủ hay gầm giường thì khói vẫn vào được và người lớn khó tìm thấy em.', 'khong_tron'),
    (3::smallint, 'multiple_choice', 'Hà đang ở nhà với bà thì ngửi thấy mùi gas nồng trong bếp. Hà nên làm gì?', 'Mở cửa sổ cho thoáng và báo ngay cho bà', 'Bật quạt điện cho bay mùi', 'Tự vặn thử các nút bếp', 'Đóng hết cửa lại', 'Mở cửa sổ cho thoáng và báo ngay cho bà', null::jsonb, 'Mở cửa giúp gas bay ra ngoài, báo bà để bà khoá van gas và xử lý an toàn.', 'mui_gas'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng khi em phát hiện cháy trong nhà?', 'Hô to báo mọi người – che mũi miệng – cúi thấp thoát ra ngoài', 'Lấy đồ chơi – đi thang máy – gọi bạn', 'Trốn vào tủ – chờ lửa tắt – đi ra ngoài', null, 'Hô to báo mọi người – che mũi miệng – cúi thấp thoát ra ngoài', null::jsonb, 'Báo cho mọi người biết, che mũi miệng rồi cúi thấp thoát ra là cách giữ an toàn khi có cháy.', 'thu_tu_thoat_chay'),
    (3::smallint, 'multiple_choice', 'Bạn Duy cầm chiếc kẹp tóc kim loại định chọc vào ổ điện. Em nên làm gì?', 'Ngăn bạn lại và nói cho bạn biết là nguy hiểm', 'Đứng xem bạn làm', 'Đưa thêm chiếc đinh cho bạn', 'Cười rồi bỏ đi', 'Ngăn bạn lại và nói cho bạn biết là nguy hiểm', null::jsonb, 'Ngăn bạn lại và giải thích là em đang giúp bạn tránh bị điện giật.', 'nhac_ban'),
    (3::smallint, 'multiple_choice', 'Việc nào KHÔNG an toàn với điện?', 'Trèo lên cột điện lấy đồ chơi', 'Tránh xa trạm biến áp', 'Lau khô tay trước khi cắm điện', 'Nhờ người lớn bật máy giặt', 'Trèo lên cột điện lấy đồ chơi', null::jsonb, 'Cột điện có dây điện mạnh, trèo lên rất nguy hiểm. Đồ chơi rơi lên đó hãy nhờ người lớn.', 'cot_dien'),
    (3::smallint, 'multiple_choice', 'Vì sao khi quần áo bị bén lửa, em KHÔNG nên chạy?', 'Vì chạy làm gió thổi vào, lửa cháy to hơn', 'Vì chạy sẽ bị mệt', 'Vì chạy làm bẩn quần áo', 'Vì chạy sẽ bị lạc', 'Vì chạy làm gió thổi vào, lửa cháy to hơn', null::jsonb, 'Gió làm lửa cháy mạnh hơn. Hãy dừng lại, nằm xuống và lăn để dập lửa.', 'dung_nam_lan')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
 where l.week_number = 7 and l.lesson_order = 7
   and not exists (select 1 from public.questions q where q.lesson_id = l.id and q.generator_type = 'ky_nang_song');

-- Kỹ năng sống • Bài 8: An toàn trong nhà và sơ cứu đơn giản (25 câu)
insert into public.lessons (subject_id, week_number, lesson_order, name, description, is_published, publish_mode)
select id, 8, 8, 'An toàn trong nhà và sơ cứu đơn giản', 'Học Vui — Kỹ năng sống, bài 8', true, 'week' from public.subjects where code = 'ky_nang_song'
on conflict (subject_id, week_number, lesson_order) do nothing;

insert into public.questions (lesson_id, difficulty, question_type, question_text, option_a, option_b, option_c, option_d,
                              correct_answer, accepted_answers, explanation, skill_tag, source_book, generator_type)
select l.id, v.difficulty, v.question_type, v.question_text, v.option_a, v.option_b, v.option_c, v.option_d,
       v.correct_answer, v.accepted_answers, v.explanation, v.skill_tag, 'Học Vui — Kỹ năng sống', 'ky_nang_song'
  from public.lessons l
  join public.subjects s on s.id = l.subject_id and s.code = 'ky_nang_song'
  cross join (values
    (1::smallint, 'multiple_choice', 'Dao, kéo, kim là những đồ vật như thế nào?', 'Sắc nhọn, dễ gây đứt tay', 'Mềm và an toàn', 'Dùng để ăn', 'Đồ chơi cho em bé', 'Sắc nhọn, dễ gây đứt tay', null::jsonb, 'Dao, kéo, kim rất sắc nhọn, dùng không cẩn thận sẽ bị đứt tay, chảy máu.', 'vat_sac_nhon'),
    (1::smallint, 'multiple_choice', 'Em chỉ được uống thuốc khi nào?', 'Khi bố mẹ hoặc bác sĩ cho uống', 'Khi thấy viên thuốc đẹp', 'Khi bạn rủ uống', 'Khi muốn ăn đồ ngọt', 'Khi bố mẹ hoặc bác sĩ cho uống', null::jsonb, 'Uống thuốc sai cách có thể làm em bị mệt, ngộ độc. Chỉ uống khi bố mẹ hoặc bác sĩ cho.', 'thuoc'),
    (1::smallint, 'multiple_choice', 'Em thấy một chai nước lạ không có nhãn trong nhà kho. Em nên làm gì?', 'Không mở ra, báo cho người lớn', 'Mở ra uống thử', 'Mở ra ngửi thử', 'Đổ ra sàn để chơi', 'Không mở ra, báo cho người lớn', null::jsonb, 'Chai lạ có thể đựng hoá chất độc. Em không mở mà báo người lớn kiểm tra.', 'hoa_chat'),
    (1::smallint, 'multiple_choice', 'Em có nên leo trèo lên lan can ban công không?', 'Không, vì có thể bị ngã từ trên cao', 'Có, để ngắm cảnh cho rõ', 'Có, nếu em bám thật chắc', null, 'Không, vì có thể bị ngã từ trên cao', null::jsonb, 'Leo lan can ban công rất dễ trượt ngã từ trên cao xuống.', 'ban_cong'),
    (1::smallint, 'multiple_choice', 'Nồi nước đang sôi trên bếp, em nên làm gì?', 'Đứng xa, không chạm vào', 'Mở nắp ra xem', 'Tự bưng nồi xuống', 'Thò tay thử nước', 'Đứng xa, không chạm vào', null::jsonb, 'Nước sôi rất nóng, có thể làm em bị bỏng. Hãy đứng xa bếp.', 'nuoc_soi'),
    (1::smallint, 'multiple_choice', 'Em có nên nhét hạt đậu, viên bi vào mũi hoặc tai không?', 'Không, vì vật có thể bị kẹt bên trong', 'Có, để chơi trò ảo thuật', 'Có, nếu hạt thật nhỏ', null, 'Không, vì vật có thể bị kẹt bên trong', null::jsonb, 'Đồ vật nhỏ nhét vào mũi, tai có thể bị kẹt, phải đi bác sĩ mới lấy ra được.', 'do_vat_nho'),
    (1::smallint, 'multiple_choice', 'Thấy sàn nhà bị ướt và trơn, em nên làm gì?', 'Đi chậm và báo người lớn lau khô', 'Chạy thật nhanh qua', 'Trượt chơi trên sàn', 'Đổ thêm nước cho vui', 'Đi chậm và báo người lớn lau khô', null::jsonb, 'Sàn ướt rất trơn, dễ bị ngã. Đi chậm và báo người lớn lau khô giúp cả nhà an toàn.', 'san_tron'),
    (1::smallint, 'multiple_choice', 'Bàn là vừa dùng xong vẫn còn nóng, em nên làm gì?', 'Không chạm vào', 'Sờ thử xem còn nóng không', 'Cầm lên chơi', 'Đặt lên giường', 'Không chạm vào', null::jsonb, 'Bàn là còn nóng rất lâu sau khi tắt, chạm vào có thể bị bỏng.', 'ban_la'),
    (1::smallint, 'text', 'Điền từ: Khi bị xước da, em rửa vết xước bằng nước ___ rồi báo người lớn.', null, null, null, null, 'sạch', '["sạch sẽ"]'::jsonb, 'Nước sạch giúp rửa trôi bụi bẩn, vết xước nhanh lành hơn.', 'vet_xuoc'),
