    (3::smallint, 'multiple_choice', 'Tuấn hứa cho Nam mượn truyện vào thứ Hai, nhưng hôm đó Tuấn quên mang. Tuấn nên làm gì?', 'Lờ đi, coi như chưa hứa', 'Trách Nam nhắc muộn', 'Xin lỗi Nam và hẹn mang vào hôm sau', 'Nói dối là truyện bị mất rồi', 'Xin lỗi Nam và hẹn mang vào hôm sau', null::jsonb, 'Khi chưa giữ được lời hứa, em xin lỗi và cố gắng thực hiện sớm nhất.', 'giu_loi_hua'),
    (3::smallint, 'multiple_choice', 'Bình lỡ làm rách vở của An, An rất buồn. Lời nói nào phù hợp nhất với Bình?', '"Vở cũ rồi, rách cũng được!"', '"Ai bảo bạn để vở ở đó!"', '"Có rách tí thôi mà!"', '"Mình xin lỗi An, mình sẽ dán lại giúp bạn nhé!"', '"Mình xin lỗi An, mình sẽ dán lại giúp bạn nhé!"', null::jsonb, 'Xin lỗi kèm việc sửa lỗi giúp bạn thấy em thật lòng.', 'sua_loi'),
