    (2::smallint, 'number', 'Bạn Lan gieo 10 hạt đậu, có 8 hạt nảy mầm. Số hạt KHÔNG nảy mầm là ___ hạt.', null, null, null, null, '2', null::jsonb, '10 - 8 = 2. Có 2 hạt không nảy mầm, có thể do hạt bị hỏng hoặc thiếu nước.', 'hat_nay_mam'),
    (2::smallint, 'multiple_choice', 'Hạt đậu đặt trên bông ẩm rồi để vào ngăn đá tủ lạnh. Hạt sẽ thế nào?', 'Khó nảy mầm vì quá lạnh', 'Nảy mầm rất nhanh', 'Biến thành cây ngay', 'Ra hoa ngay', 'Khó nảy mầm vì quá lạnh', null::jsonb, 'Hạt cần nhiệt độ ấm áp để nảy mầm. Trong ngăn đá quá lạnh nên hạt không nảy mầm được.', 'hat_nay_mam'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng cho các bước gieo hạt?', 'Làm đất tơi xốp → gieo hạt → lấp đất mỏng → tưới nước', 'Tưới nước → lấp đất → gieo hạt → làm đất', 'Gieo hạt → làm đất → tưới nước → lấp đất', 'Lấp đất → tưới nước → làm đất → gieo hạt', 'Làm đất tơi xốp → gieo hạt → lấp đất mỏng → tưới nước', null::jsonb, 'Đầu tiên làm đất cho tơi xốp, rồi gieo hạt, phủ một lớp đất mỏng và tưới nước nhẹ.', 'gieo_hat'),
    (3::smallint, 'multiple_choice', 'Bạn Hùng có hai cốc hạt đậu: một cốc lót bông ẩm, một cốc lót bông khô. Sau 3 ngày, cốc nào có hạt nảy mầm?', 'Chỉ cốc lót bông ẩm', 'Chỉ cốc lót bông khô', 'Không cốc nào nảy mầm', null, 'Chỉ cốc lót bông ẩm', null::jsonb, 'Hạt cần nước để nảy mầm. Bông ẩm có nước nên hạt nảy mầm, bông khô thì không.', 'hat_nay_mam'),
    (3::smallint, 'multiple_choice', 'Bình gieo hạt quá dày, cây con mọc chen chúc nhau. Bình nên làm gì để cây lớn tốt?', 'Nhổ bớt cây yếu để cây còn lại đủ chỗ và ánh sáng', 'Gieo thêm thật nhiều hạt nữa', 'Che kín luống cây cho tối', 'Không tưới nước nữa', 'Nhổ bớt cây yếu để cây còn lại đủ chỗ và ánh sáng', null::jsonb, 'Cây mọc quá dày sẽ tranh nhau ánh sáng, nước và chất khoáng. Tỉa bớt giúp cây còn lại lớn khỏe.', 'cham_soc_cay'),
    (3::smallint, 'multiple_choice', 'Việc nào KHÔNG giúp cây lớn tốt?', 'Đổ nước ngập chậu suốt cả ngày', 'Tưới nước vừa đủ', 'Bón phân hợp lí', 'Đặt cây nơi có ánh sáng', 'Đổ nước ngập chậu suốt cả ngày', null::jsonb, 'Nước ngập lâu làm rễ bị úng, thối. Cây chỉ cần tưới vừa đủ.', 'tuoi_nuoc'),
    (3::smallint, 'multiple_choice', 'Chậu cây được tưới đủ nước, đất tốt nhưng để trong góc nhà tối nên lá bị vàng. Em nên làm gì?', 'Đưa chậu cây ra chỗ có ánh sáng', 'Tưới thêm thật nhiều nước', 'Cất cây vào trong tủ', 'Ngắt hết lá đi', 'Đưa chậu cây ra chỗ có ánh sáng', null::jsonb, 'Cây đã đủ nước và chất khoáng, chỉ còn thiếu ánh sáng. Đưa cây ra chỗ sáng, lá sẽ xanh lại.', 'anh_sang'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng về sự lớn lên của cây đậu?', 'Hạt → nảy mầm → cây con → cây ra hoa, kết quả', 'Cây con → hạt → ra hoa → nảy mầm', 'Ra hoa → hạt → cây con → nảy mầm', 'Nảy mầm → ra hoa → hạt → cây con', 'Hạt → nảy mầm → cây con → cây ra hoa, kết quả', null::jsonb, 'Hạt nảy mầm thành cây con, cây con lớn dần rồi ra hoa, kết quả. Trong quả lại có hạt mới.', 'hat_nay_mam'),
    (3::smallint, 'multiple_choice', 'Bạn Na muốn biết cây có cần ánh sáng không. Na nên làm thí nghiệm nào?', 'Hai chậu cây giống nhau, tưới như nhau, một chậu để chỗ sáng, một chậu úp hộp tối', 'Tưới nước một chậu, chậu kia không tưới', 'Để cả hai chậu trong hộp tối', 'Bón phân một chậu, chậu kia không bón', 'Hai chậu cây giống nhau, tưới như nhau, một chậu để chỗ sáng, một chậu úp hộp tối', null::jsonb, 'Muốn thử ánh sáng, hai chậu chỉ khác nhau ở ánh sáng, còn nước và đất phải như nhau.', 'anh_sang')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
 where l.week_number = 7 and l.lesson_order = 7
   and not exists (select 1 from public.questions q where q.lesson_id = l.id and q.generator_type = 'khoa_hoc');

-- Khoa học • Bài 8: Nơi sống của thực vật và động vật (25 câu)
insert into public.lessons (subject_id, week_number, lesson_order, name, description, is_published, publish_mode)
select id, 8, 8, 'Nơi sống của thực vật và động vật', 'Học Vui — Khoa học, bài 8', true, 'week' from public.subjects where code = 'khoa_hoc'
on conflict (subject_id, week_number, lesson_order) do nothing;

insert into public.questions (lesson_id, difficulty, question_type, question_text, option_a, option_b, option_c, option_d,
                              correct_answer, accepted_answers, explanation, skill_tag, source_book, generator_type)
select l.id, v.difficulty, v.question_type, v.question_text, v.option_a, v.option_b, v.option_c, v.option_d,
