  join public.subjects s on s.id = l.subject_id and s.code = 'khoa_hoc'
  cross join (values
    (1::smallint, 'multiple_choice', 'Con cá chép sống ở đâu?', 'Dưới nước', 'Trên cây', 'Trong sa mạc', 'Trên núi tuyết', 'Dưới nước', null::jsonb, 'Cá chép sống dưới nước ở ao, hồ, sông.', 'duoi_nuoc'),
    (1::smallint, 'multiple_choice', 'Cây nào sau đây sống trên cạn?', 'Cây bàng', 'Cây sen', 'Cây súng', 'Cây bèo', 'Cây bàng', null::jsonb, 'Cây bàng mọc trên đất. Sen, súng, bèo là những cây sống dưới nước.', 'tren_can'),
    (1::smallint, 'multiple_choice', 'Cây xương rồng thường sống ở nơi nào?', 'Sa mạc khô nóng', 'Dưới đáy ao', 'Dưới biển', 'Trong hồ nước', 'Sa mạc khô nóng', null::jsonb, 'Cây xương rồng chịu được khô hạn nên sống tốt ở sa mạc khô nóng.', 'sa_mac'),
