    (1::smallint, 'multiple_choice', 'Gấu bắc cực sống ở đâu?', 'Vùng băng giá lạnh lẽo', 'Sa mạc nóng', 'Dưới đáy sông', 'Trong ao làng', 'Vùng băng giá lạnh lẽo', null::jsonb, 'Gấu bắc cực sống ở vùng băng tuyết quanh Bắc Cực, nơi rất lạnh.', 'vung_bang'),
    (1::smallint, 'multiple_choice', 'Cá thở bằng bộ phận nào?', 'Mang', 'Phổi', 'Vây', 'Đuôi', 'Mang', null::jsonb, 'Cá thở bằng mang. Mang giúp cá lấy khí ô-xi hoà tan trong nước.', 'cach_tho'),
