    (1::smallint, 'multiple_choice', 'Con vật nào sống trong rừng, hay chuyền cành trên cây?', 'Con khỉ', 'Con cá voi', 'Con tôm', 'Con sứa', 'Con khỉ', null::jsonb, 'Khỉ sống trong rừng, chuyền cành giỏi và ăn quả, lá cây.', 'tren_can'),
    (1::smallint, 'multiple_choice', 'Việc làm nào giúp bảo vệ nơi sống của cá và tôm?', 'Không xả rác xuống sông, hồ', 'Đổ dầu xuống ao', 'Ném túi ni-lông xuống sông', 'Đổ nước bẩn ra hồ', 'Không xả rác xuống sông, hồ', null::jsonb, 'Sông, hồ sạch là ngôi nhà tốt cho cá, tôm. Rác thải làm nước bẩn, các con vật dễ bị chết.', 'bao_ve_noi_song'),
    (1::smallint, 'multiple_choice', 'Cây bèo thường sống ở đâu?', 'Trên mặt nước ao, hồ', 'Trên sa mạc', 'Trên đỉnh núi đá', 'Trên cành cây cao', 'Trên mặt nước ao, hồ', null::jsonb, 'Bèo nổi trên mặt nước ao, hồ, rễ bèo buông xuống nước.', 'duoi_nuoc'),
    (2::smallint, 'multiple_choice', 'Vì sao gấu bắc cực không bị lạnh ở vùng băng giá?', 'Vì có bộ lông dày và lớp mỡ dày dưới da', 'Vì gấu thở bằng mang', 'Vì gấu luôn ở trong nước ấm', 'Vì gấu có lông vũ như chim', 'Vì có bộ lông dày và lớp mỡ dày dưới da', null::jsonb, 'Bộ lông dày và lớp mỡ dày như chiếc áo ấm, giúp gấu bắc cực giữ ấm cơ thể.', 'vung_bang'),
    (2::smallint, 'multiple_choice', 'Vì sao lạc đà sống được ở sa mạc khô nóng?', 'Vì lạc đà nhịn khát giỏi, đi được lâu trên cát nóng', 'Vì lạc đà thở bằng mang', 'Vì lạc đà có lông vũ', 'Vì lạc đà thích sống dưới nước', 'Vì lạc đà nhịn khát giỏi, đi được lâu trên cát nóng', null::jsonb, 'Lạc đà có thể nhiều ngày không uống nước, chân to bè giúp đi trên cát không bị lún.', 'sa_mac'),
    (2::smallint, 'multiple_choice', 'Lá cây xương rồng biến thành gai, thân dày và mọng nước. Điều đó giúp cây thế nào?', 'Giữ được nước để sống nơi khô hạn', 'Hút được nhiều nước biển', 'Bơi được trong nước', 'Chịu được băng tuyết', 'Giữ được nước để sống nơi khô hạn', null::jsonb, 'Lá biến thành gai giúp cây ít mất nước, thân mọng trữ nước, nhờ vậy xương rồng sống được ở sa mạc.', 'sa_mac'),
    (2::smallint, 'multiple_choice', 'Nơi sống cung cấp cho con vật những gì?', 'Thức ăn, nước uống và chỗ ở', 'Chỉ có đồ chơi', 'Quần áo và giày dép', 'Chỉ có ánh đèn', 'Thức ăn, nước uống và chỗ ở', null::jsonb, 'Nơi sống là ngôi nhà của con vật, có thức ăn, nước uống và chỗ để ở, để trú ẩn.', 'vai_tro_noi_song'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm các cây sống dưới nước?', 'Sen, súng, rong', 'Xương rồng, bàng, phượng', 'Ngô, mía, chuối', 'Cam, bưởi, xoài', 'Sen, súng, rong', null::jsonb, 'Sen, súng, rong đều sống trong nước ở ao, hồ, sông hoặc biển.', 'duoi_nuoc'),
    (2::smallint, 'multiple_choice', 'Vì sao cá bị đưa lên cạn lâu sẽ chết?', 'Vì cá thở bằng mang, chỉ thở được trong nước', 'Vì cá sợ ánh nắng', 'Vì cá không có chân để đi', 'Vì cá không thích đất', 'Vì cá thở bằng mang, chỉ thở được trong nước', null::jsonb, 'Mang cá chỉ lấy được khí ô-xi trong nước. Lên cạn lâu, cá không thở được nên sẽ chết.', 'cach_tho'),
    (2::smallint, 'multiple_choice', 'Vì sao không nên chặt phá rừng?', 'Vì rừng là nơi sống của rất nhiều loài cây và con vật', 'Vì rừng làm không khí bẩn hơn', 'Vì rừng không có con vật nào', 'Vì cây rừng không có ích', 'Vì rừng là nơi sống của rất nhiều loài cây và con vật', null::jsonb, 'Chặt phá rừng làm nhiều con vật mất nhà, mất thức ăn. Rừng còn cho không khí trong lành.', 'bao_ve_noi_song'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm các con vật vừa sống được trên cạn vừa sống được dưới nước?', 'Ếch, cá sấu, cua', 'Cá chép, cá rô, mực', 'Gà, mèo, chó', 'Lạc đà, ngựa, thỏ', 'Ếch, cá sấu, cua', null::jsonb, 'Ếch, cá sấu, cua có thể ở dưới nước và cũng lên bờ được.', 'can_va_nuoc'),
    (3::smallint, 'multiple_choice', 'Con vật nào KHÔNG sống dưới nước?', 'Con thỏ', 'Con cá chép', 'Con tôm', 'Con mực', 'Con thỏ', null::jsonb, 'Thỏ sống trên cạn, đào hang và ăn cỏ. Cá chép, tôm, mực đều sống dưới nước.', 'tren_can'),
    (3::smallint, 'multiple_choice', 'Nếu cái ao bị lấp đầy đất để xây nhà, con vật nào sẽ mất nơi sống?', 'Con cá rô', 'Con trâu', 'Con gà', 'Con mèo', 'Con cá rô', null::jsonb, 'Cá rô sống dưới nước trong ao. Ao bị lấp thì cá rô không còn chỗ sống.', 'bao_ve_noi_song'),
    (3::smallint, 'multiple_choice', 'Gấu bắc cực và lạc đà khác nhau thế nào về nơi sống?', 'Gấu bắc cực sống ở vùng băng giá, lạc đà sống ở sa mạc', 'Gấu bắc cực sống ở sa mạc, lạc đà sống ở vùng băng giá', 'Chúng cùng sống dưới đáy biển', 'Chúng cùng sống trong ao làng', 'Gấu bắc cực sống ở vùng băng giá, lạc đà sống ở sa mạc', null::jsonb, 'Mỗi con vật hợp với một nơi sống: gấu bắc cực chịu lạnh giỏi, lạc đà chịu nóng và khát giỏi.', 'vai_tro_noi_song'),
    (3::smallint, 'multiple_choice', 'Cá heo và cá chép đều sống dưới nước. Chúng khác nhau thế nào về cách thở?', 'Cá heo thở bằng phổi nên phải ngoi lên, cá chép thở bằng mang', 'Cá heo thở bằng mang, cá chép thở bằng phổi', 'Chúng đều thở bằng mang', 'Cá heo không cần thở', 'Cá heo thở bằng phổi nên phải ngoi lên, cá chép thở bằng mang', null::jsonb, 'Cá heo thở bằng phổi nên thỉnh thoảng phải ngoi lên mặt nước lấy không khí. Cá chép thở bằng mang ngay trong nước.', 'cach_tho'),
    (3::smallint, 'multiple_choice', 'Vì sao cây sen không sống được ở sa mạc?', 'Vì sa mạc rất khô, mà sen cần sống trong nước', 'Vì sa mạc quá lạnh', 'Vì sa mạc có quá nhiều nước', 'Vì sa mạc không có ánh sáng', 'Vì sa mạc rất khô, mà sen cần sống trong nước', null::jsonb, 'Sen là cây sống dưới nước. Sa mạc khô nóng, rất ít nước nên sen không sống được.', 'duoi_nuoc'),
    (3::smallint, 'multiple_choice', 'Điều nào ĐÚNG về nơi sống của sinh vật?', 'Mỗi loài thích hợp với một nơi sống riêng', 'Cá sống tốt nhất trên cạn', 'Lạc đà sống ở vùng băng giá', 'Cây sen sống ở sa mạc', 'Mỗi loài thích hợp với một nơi sống riêng', null::jsonb, 'Mỗi cây, mỗi con vật có đặc điểm phù hợp với nơi sống của mình, như cá hợp với nước, lạc đà hợp với sa mạc.', 'vai_tro_noi_song'),
    (3::smallint, 'multiple_choice', 'Rùa biển hay ăn nhầm túi ni-lông vì tưởng là con sứa. Em có thể làm gì để giúp rùa biển?', 'Không vứt túi ni-lông, nhặt rác khi đi biển', 'Thả thêm túi ni-lông xuống biển', 'Bắt rùa biển về nuôi trong chậu', 'Đổ nước bẩn ra biển', 'Không vứt túi ni-lông, nhặt rác khi đi biển', null::jsonb, 'Giữ biển sạch là bảo vệ nơi sống của rùa biển và nhiều sinh vật khác.', 'bao_ve_noi_song')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
 where l.week_number = 8 and l.lesson_order = 8
