    (1::smallint, 'multiple_choice', 'Con mèo thuộc nhóm động vật nào?', 'Thú', 'Chim', 'Cá', 'Bò sát', 'Thú', null::jsonb, 'Mèo có lông mao, đẻ con và nuôi con bằng sữa nên thuộc nhóm thú.', 'nhom_thu'),
    (2::smallint, 'number', 'Côn trùng có ___ chân.', null, null, null, null, '6', null::jsonb, 'Côn trùng như ong, kiến, bướm đều có 6 chân.', 'con_trung'),
    (2::smallint, 'multiple_choice', 'Con dơi biết bay nhưng lại thuộc nhóm thú. Vì sao?', 'Vì dơi đẻ con và nuôi con bằng sữa', 'Vì dơi có lông vũ', 'Vì dơi đẻ trứng', 'Vì dơi có mỏ', 'Vì dơi đẻ con và nuôi con bằng sữa', null::jsonb, 'Dơi có lông mao, đẻ con và nuôi con bằng sữa nên là thú, dù biết bay.', 'nhom_thu'),
    (2::smallint, 'multiple_choice', 'Nhóm động vật nào có bộ lông mao?', 'Thú', 'Chim', 'Cá', 'Bò sát', 'Thú', null::jsonb, 'Lông mao là loại lông mềm như lông chó, lông mèo. Đó là đặc điểm của nhóm thú.', 'nhom_thu'),
    (2::smallint, 'multiple_choice', 'Chim cánh cụt không bay được nhưng vẫn thuộc nhóm chim. Vì sao?', 'Vì có lông vũ, có mỏ, có hai cánh và đẻ trứng', 'Vì đẻ con và nuôi con bằng sữa', 'Vì thở bằng mang', 'Vì có 6 chân', 'Vì có lông vũ, có mỏ, có hai cánh và đẻ trứng', null::jsonb, 'Chim cánh cụt có đủ đặc điểm của chim, chỉ là cánh dùng để bơi chứ không bay được.', 'nhom_chim'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm toàn côn trùng?', 'Ong, kiến, bướm', 'Ong, nhện, gà', 'Kiến, cá, mèo', 'Bướm, rắn, ếch', 'Ong, kiến, bướm', null::jsonb, 'Ong, kiến, bướm đều có 6 chân và cơ thể chia 3 phần nên là côn trùng.', 'con_trung'),
    (2::smallint, 'multiple_choice', 'Nòng nọc lớn lên sẽ thành con gì?', 'Con ếch', 'Con cá', 'Con rắn', 'Con thằn lằn', 'Con ếch', null::jsonb, 'Nòng nọc sống dưới nước, có đuôi. Lớn lên, nòng nọc mọc chân, rụng đuôi và thành ếch.', 'luong_cu'),
    (2::smallint, 'multiple_choice', 'Rắn, thằn lằn, cá sấu cùng thuộc một nhóm. Đó là nhóm nào?', 'Bò sát', 'Lưỡng cư', 'Thú', 'Cá', 'Bò sát', null::jsonb, 'Rắn, thằn lằn, cá sấu đều có da phủ vảy và đẻ trứng nên thuộc nhóm bò sát.', 'bo_sat'),
    (2::smallint, 'multiple_choice', 'Đặc điểm nào là của nhóm cá?', 'Sống dưới nước, thở bằng mang, có vây', 'Có lông vũ và hai cánh', 'Có 6 chân và cơ thể 3 phần', 'Có lông mao, nuôi con bằng sữa', 'Sống dưới nước, thở bằng mang, có vây', null::jsonb, 'Cá sống dưới nước, thở bằng mang, bơi nhờ vây và thường có vảy bao quanh thân.', 'nhom_ca'),
    (3::smallint, 'multiple_choice', 'Con vật có 6 chân, có cánh, cơ thể chia làm 3 phần. Đó là nhóm nào?', 'Côn trùng', 'Chim', 'Thú', 'Bò sát', 'Côn trùng', null::jsonb, '6 chân và cơ thể 3 phần (đầu, ngực, bụng) là đặc điểm của côn trùng, như chuồn chuồn, ong.', 'con_trung'),
    (3::smallint, 'multiple_choice', 'Con vật nào KHÔNG thuộc nhóm côn trùng?', 'Con nhện', 'Con kiến', 'Con bướm', 'Con chuồn chuồn', 'Con nhện', null::jsonb, 'Nhện có 8 chân nên không phải côn trùng. Kiến, bướm, chuồn chuồn có 6 chân.', 'con_trung'),
    (3::smallint, 'multiple_choice', 'Con vật nào KHÔNG thuộc nhóm thú?', 'Con gà', 'Con dơi', 'Con cá heo', 'Con voi', 'Con gà', null::jsonb, 'Gà có lông vũ, đẻ trứng nên là chim. Dơi, cá heo, voi đều nuôi con bằng sữa nên là thú.', 'nhom_thu'),
    (3::smallint, 'multiple_choice', 'Con vật nào KHÔNG thuộc nhóm chim?', 'Con dơi', 'Đà điểu', 'Chim cánh cụt', 'Con vịt', 'Con dơi', null::jsonb, 'Dơi biết bay nhưng là thú. Đà điểu, chim cánh cụt, vịt đều có lông vũ, đẻ trứng nên là chim.', 'nhom_chim'),
    (3::smallint, 'multiple_choice', 'Một con vật sống dưới biển, thở bằng phổi, đẻ con và nuôi con bằng sữa. Nó thuộc nhóm nào?', 'Thú', 'Cá', 'Lưỡng cư', 'Bò sát', 'Thú', null::jsonb, 'Đẻ con và nuôi con bằng sữa là đặc điểm của thú. Cá voi, cá heo là thú sống dưới nước.', 'nhom_thu'),
    (3::smallint, 'multiple_choice', 'Điểm khác nhau giữa chim và thú là gì?', 'Chim đẻ trứng, thú đẻ con và nuôi con bằng sữa', 'Chim đẻ con, thú đẻ trứng', 'Chim có lông mao, thú có lông vũ', 'Chim có 4 chân, thú có 2 chân', 'Chim đẻ trứng, thú đẻ con và nuôi con bằng sữa', null::jsonb, 'Chim có lông vũ và đẻ trứng. Thú có lông mao, đẻ con và nuôi con bằng sữa.', 'nhom_thu'),
    (3::smallint, 'number', 'Nhà bạn Minh có 1 con gà và 1 con chó. Cả hai con có tất cả ___ chân.', null, null, null, null, '6', null::jsonb, 'Gà có 2 chân, chó có 4 chân. 2 + 4 = 6 chân.', 'so_chan')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
