    (1::smallint, 'multiple_choice', 'Con rắn di chuyển bằng cách nào?', 'Bò, trườn bằng thân', 'Bay bằng cánh', 'Nhảy bằng hai chân', 'Chạy bằng bốn chân', 'Bò, trườn bằng thân', null::jsonb, 'Rắn không có chân, rắn uốn mình để bò, trườn đi.', 'di_chuyen'),
    (1::smallint, 'multiple_choice', 'Con kangaroo di chuyển bằng cách nào?', 'Nhảy', 'Bơi', 'Bay', 'Trườn', 'Nhảy', null::jsonb, 'Kangaroo có hai chân sau rất khỏe, nhảy được rất xa.', 'di_chuyen'),
    (1::smallint, 'multiple_choice', 'Con ong bay đến bông hoa để lấy gì?', 'Mật hoa', 'Lá cây', 'Đất', 'Nước muối', 'Mật hoa', null::jsonb, 'Ong hút mật hoa để làm thành mật ong.', 'ong_thu_phan'),
    (1::smallint, 'multiple_choice', 'Con chó di chuyển bằng cách nào?', 'Đi và chạy bằng bốn chân', 'Bay bằng cánh', 'Trườn bằng bụng', 'Bơi bằng vây', 'Đi và chạy bằng bốn chân', null::jsonb, 'Chó có bốn chân khỏe, đi và chạy rất nhanh.', 'di_chuyen'),
    (1::smallint, 'text', 'Điền từ: Gấu ngủ suốt mùa đông lạnh giá, người ta gọi là ngủ ___.', null, null, null, null, 'đông', '["mùa đông"]'::jsonb, 'Mùa đông lạnh và ít thức ăn nên gấu tìm hang ngủ một giấc dài, gọi là ngủ đông.', 'ngu_dong'),
    (1::smallint, 'multiple_choice', 'Con vật nào ăn tạp, ăn được cả thịt và thực vật?', 'Con lợn', 'Con bò', 'Con hổ', 'Con thỏ', 'Con lợn', null::jsonb, 'Lợn ăn được cả cám, rau và thịt, cá nên là động vật ăn tạp.', 'an_tap'),
    (2::smallint, 'multiple_choice', 'Vì sao răng của hổ nhọn và sắc?', 'Để xé thịt con mồi', 'Để nghiền cỏ', 'Để hút mật hoa', 'Để mổ thóc', 'Để xé thịt con mồi', null::jsonb, 'Hổ ăn thịt nên cần răng nhọn, sắc để cắn và xé thịt.', 'rang'),
    (2::smallint, 'multiple_choice', 'Răng hàm của bò to và phẳng. Điều đó giúp bò làm gì?', 'Nghiền nát cỏ', 'Xé thịt', 'Bắt cá', 'Hút mật hoa', 'Nghiền nát cỏ', null::jsonb, 'Động vật ăn cỏ có răng phẳng để nghiền nát cỏ, lá cây.', 'rang'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm toàn động vật ăn cỏ?', 'Trâu, thỏ, hươu cao cổ', 'Hổ, sư tử, cá mập', 'Lợn, gà, gấu', 'Đại bàng, hổ, thỏ', 'Trâu, thỏ, hươu cao cổ', null::jsonb, 'Trâu, thỏ, hươu cao cổ ăn cỏ, lá cây. Hổ, sư tử, cá mập ăn thịt; lợn, gà, gấu ăn tạp.', 'an_co'),
    (2::smallint, 'multiple_choice', 'Khi ong bay từ hoa này sang hoa khác, ong giúp gì cho hoa?', 'Giúp hoa thụ phấn để tạo thành quả', 'Làm hoa héo nhanh', 'Ăn hết lá cây', 'Làm cây bị đổ', 'Giúp hoa thụ phấn để tạo thành quả', null::jsonb, 'Phấn hoa dính vào ong và được mang sang hoa khác. Nhờ vậy hoa được thụ phấn và kết quả.', 'ong_thu_phan'),
    (2::smallint, 'multiple_choice', 'Con voi rất to lớn. Thức ăn chủ yếu của voi là gì?', 'Cỏ, lá cây, cành non và quả', 'Thịt các con vật khác', 'Cá dưới sông', 'Côn trùng nhỏ', 'Cỏ, lá cây, cành non và quả', null::jsonb, 'Voi là động vật ăn thực vật. Mỗi ngày voi ăn rất nhiều cỏ, lá cây và cành non.', 'an_co'),
