    (2::smallint, 'multiple_choice', 'Vì sao gấu ăn thật nhiều trước khi mùa đông đến?', 'Để tích mỡ, có sức ngủ đông suốt mùa lạnh', 'Để chạy nhanh hơn', 'Để bay được', 'Để bơi xuống biển', 'Để tích mỡ, có sức ngủ đông suốt mùa lạnh', null::jsonb, 'Gấu ăn nhiều để tích mỡ trong cơ thể. Khi ngủ đông, gấu dùng lớp mỡ đó để sống qua mùa lạnh.', 'ngu_dong'),
    (3::smallint, 'multiple_choice', 'Chuỗi thức ăn nào được sắp xếp đúng?', 'Lá cây → Sâu → Chim', 'Chim → Sâu → Lá cây', 'Sâu → Lá cây → Chim', 'Lá cây → Chim → Sâu', 'Lá cây → Sâu → Chim', null::jsonb, 'Sâu ăn lá cây, chim ăn sâu. Chuỗi thức ăn thường bắt đầu từ cây xanh.', 'chuoi_thuc_an'),
    (3::smallint, 'multiple_choice', 'Trong chuỗi thức ăn: Cỏ → Thỏ → Cáo, nếu cỏ bị khô héo hết thì điều gì xảy ra?', 'Thỏ thiếu thức ăn, rồi cáo cũng thiếu thức ăn', 'Cáo có nhiều thức ăn hơn', 'Thỏ sẽ đông hơn', 'Không có gì thay đổi', 'Thỏ thiếu thức ăn, rồi cáo cũng thiếu thức ăn', null::jsonb, 'Thỏ ăn cỏ, cáo ăn thỏ. Hết cỏ thì thỏ đói và ít đi, cáo cũng thiếu thức ăn theo.', 'chuoi_thuc_an'),
    (3::smallint, 'multiple_choice', 'Con vật nào KHÔNG phải động vật ăn thịt?', 'Hươu cao cổ', 'Sư tử', 'Cá mập', 'Đại bàng', 'Hươu cao cổ', null::jsonb, 'Hươu cao cổ ăn lá cây trên cao. Sư tử, cá mập, đại bàng đều săn mồi để ăn thịt.', 'an_thit'),
    (3::smallint, 'multiple_choice', 'Một con vật có răng nanh dài, nhọn, sắc và móng vuốt khỏe. Nó có thể là động vật ăn gì?', 'Ăn thịt', 'Ăn cỏ', 'Ăn mật hoa', null, 'Ăn thịt', null::jsonb, 'Răng nanh nhọn và móng vuốt khỏe giúp con vật bắt mồi, xé thịt.', 'rang'),
    (3::smallint, 'multiple_choice', 'Nhóm nào gồm các con vật di chuyển bằng cách bay?', 'Chim sẻ, dơi, ong', 'Cá, rắn, sâu', 'Ngựa, chó, mèo', 'Kangaroo, ếch, châu chấu', 'Chim sẻ, dơi, ong', null::jsonb, 'Chim sẻ, dơi, ong đều có cánh để bay. Dơi là thú nhưng vẫn biết bay.', 'di_chuyen'),
    (3::smallint, 'multiple_choice', 'Con vật nào KHÔNG di chuyển bằng cách nhảy?', 'Con rắn', 'Con kangaroo', 'Con ếch', 'Con châu chấu', 'Con rắn', null::jsonb, 'Rắn không có chân, rắn bò trườn. Kangaroo, ếch, châu chấu đều nhảy giỏi.', 'di_chuyen'),
    (3::smallint, 'multiple_choice', 'Bạn Hà nói: "Con gà ăn thóc nên là động vật ăn cỏ." Thật ra gà còn ăn sâu, giun. Vậy gà thuộc nhóm nào?', 'Ăn tạp', 'Ăn cỏ', 'Ăn thịt', null, 'Ăn tạp', null::jsonb, 'Gà ăn cả thóc, rau (thực vật) và sâu, giun (động vật) nên gà là động vật ăn tạp.', 'an_tap')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
