-- Khoa học • Bài 11: Vòng đời của sinh vật (25 câu)
insert into public.lessons (subject_id, week_number, lesson_order, name, description, is_published, publish_mode)
select id, 11, 11, 'Vòng đời của sinh vật', 'Học Vui — Khoa học, bài 11', true, 'week' from public.subjects where code = 'khoa_hoc'
on conflict (subject_id, week_number, lesson_order) do nothing;

insert into public.questions (lesson_id, difficulty, question_type, question_text, option_a, option_b, option_c, option_d,
                              correct_answer, accepted_answers, explanation, skill_tag, source_book, generator_type)
select l.id, v.difficulty, v.question_type, v.question_text, v.option_a, v.option_b, v.option_c, v.option_d,
       v.correct_answer, v.accepted_answers, v.explanation, v.skill_tag, 'Học Vui — Khoa học', 'khoa_hoc'
  from public.lessons l
  join public.subjects s on s.id = l.subject_id and s.code = 'khoa_hoc'
  cross join (values
    (1::smallint, 'multiple_choice', 'Bướm mẹ đẻ ra gì?', 'Trứng', 'Sâu con', 'Bướm con', null, 'Trứng', null::jsonb, 'Bướm mẹ đẻ trứng, thường dính dưới lá cây. Từ trứng sẽ nở ra sâu non.', 'vong_doi_buom'),
    (1::smallint, 'multiple_choice', 'Con non của ếch, có đuôi và sống dưới nước, gọi là gì?', 'Nòng nọc', 'Bọ gậy', 'Sâu', 'Nhộng', 'Nòng nọc', null::jsonb, 'Trứng ếch nở ra nòng nọc. Nòng nọc có đuôi để bơi dưới nước.', 'vong_doi_ech'),
    (1::smallint, 'multiple_choice', 'Gà con nở ra từ đâu?', 'Quả trứng', 'Hạt thóc', 'Cái kén', null, 'Quả trứng', null::jsonb, 'Gà mẹ đẻ trứng rồi ấp, khoảng ba tuần sau gà con mổ vỏ chui ra.', 'vong_doi_ga'),
    (1::smallint, 'multiple_choice', 'Con non của muỗi sống trong nước, còn gọi là lăng quăng, có tên là gì?', 'Bọ gậy', 'Nòng nọc', 'Sâu non', null, 'Bọ gậy', null::jsonb, 'Trứng muỗi nở ra bọ gậy (lăng quăng) sống trong nước, lớn lên thành muỗi.', 'vong_doi_muoi'),
    (1::smallint, 'multiple_choice', 'Cây đậu mọc lên từ đâu?', 'Hạt đậu', 'Lá đậu', 'Hoa đậu', null, 'Hạt đậu', null::jsonb, 'Gieo hạt đậu xuống đất ẩm, hạt nảy mầm rồi lớn thành cây đậu.', 'vong_doi_cay'),
    (1::smallint, 'multiple_choice', 'Con vật nào sau đây đẻ trứng?', 'Con gà', 'Con chó', 'Con mèo', 'Con bò', 'Con gà', null::jsonb, 'Gà đẻ trứng. Chó, mèo, bò đẻ con và nuôi con bằng sữa.', 'de_trung_de_con'),
    (1::smallint, 'multiple_choice', 'Con vật nào sau đây đẻ con?', 'Con mèo', 'Con vịt', 'Con rùa', 'Con cá chép', 'Con mèo', null::jsonb, 'Mèo mẹ đẻ ra mèo con và cho con bú sữa. Vịt, rùa, cá chép đều đẻ trứng.', 'de_trung_de_con'),
    (1::smallint, 'multiple_choice', 'Sâu bướm ăn lá lớn dần, rồi cuộn mình trong kén. Lúc nằm trong kén nó được gọi là gì?', 'Nhộng', 'Nòng nọc', 'Trứng', null, 'Nhộng', null::jsonb, 'Sâu làm kén và hóa nhộng. Ít lâu sau, bướm chui ra từ kén.', 'vong_doi_buom'),
    (1::smallint, 'text', 'Điền từ: Em bé lớn lên thành trẻ em, rồi thành người ___, cuối cùng là người già.', null, null, null, null, 'lớn', '["lon","trưởng thành"]'::jsonb, 'Con người lớn lên theo các giai đoạn: em bé, trẻ em, người lớn, người già.', 'vong_doi_nguoi'),
    (1::smallint, 'multiple_choice', 'Muỗi thường đẻ trứng ở đâu?', 'Chỗ nước đọng', 'Trên cành cây khô', 'Trong đống cát khô', null, 'Chỗ nước đọng', null::jsonb, 'Muỗi đẻ trứng ở nơi có nước đọng như chum, lọ, lốp xe cũ chứa nước mưa.', 'vong_doi_muoi'),
    (2::smallint, 'multiple_choice', 'Vì sao cần đổ bỏ nước đọng trong chum, lọ, lốp xe cũ quanh nhà?', 'Để muỗi không có chỗ đẻ trứng', 'Để cây cối mọc nhanh hơn', 'Để nước không bị đóng băng', 'Để cá có chỗ bơi', 'Để muỗi không có chỗ đẻ trứng', null::jsonb, 'Không còn nước đọng thì muỗi không đẻ trứng được, bọ gậy không sống được, nhà em sẽ ít muỗi hơn.', 'phong_muoi'),
    (2::smallint, 'multiple_choice', 'Khi nòng nọc lớn dần, cơ thể nó thay đổi thế nào?', 'Mọc chân, đuôi ngắn dần', 'Mọc cánh rồi bay đi', 'Đuôi dài thêm, không có chân', null, 'Mọc chân, đuôi ngắn dần', null::jsonb, 'Nòng nọc mọc chân sau, rồi chân trước, đuôi ngắn dần và thành ếch con.', 'vong_doi_ech'),
    (2::smallint, 'number', 'Vòng đời của bướm gồm trứng, sâu, nhộng và bướm. Vòng đời đó có mấy giai đoạn?', null, null, null, null, '4', null::jsonb, 'Bướm trải qua 4 giai đoạn: trứng → sâu → nhộng → bướm.', 'vong_doi_buom'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm toàn những con vật đẻ trứng?', 'Gà, vịt, rùa', 'Chó, mèo, gà', 'Bò, vịt, cá', 'Mèo, rùa, chó', 'Gà, vịt, rùa', null::jsonb, 'Gà, vịt, rùa đều đẻ trứng. Chó, mèo, bò là những con vật đẻ con.', 'de_trung_de_con'),
    (2::smallint, 'multiple_choice', 'Bạn Lan gieo hạt đậu vào chậu đất. Lan cần làm gì để hạt nảy mầm?', 'Tưới nước cho đất đủ ẩm', 'Rắc muối lên hạt', 'Để chậu vào ngăn đá tủ lạnh', 'Đổ dầu ăn vào chậu', 'Tưới nước cho đất đủ ẩm', null::jsonb, 'Hạt cần nước, không khí và độ ấm vừa phải mới nảy mầm được.', 'nay_mam'),
    (2::smallint, 'multiple_choice', 'Con sâu bướm và con bướm có quan hệ thế nào?', 'Sâu là con non, lớn lên thành bướm', 'Bướm lớn lên sẽ thành sâu', 'Sâu và bướm không liên quan gì', null, 'Sâu là con non, lớn lên thành bướm', null::jsonb, 'Sâu chính là bướm lúc còn nhỏ. Sâu hóa nhộng rồi mới thành bướm.', 'vong_doi_buom'),
    (2::smallint, 'multiple_choice', 'Cây ra hoa để làm gì?', 'Để kết quả và tạo ra hạt', 'Để rễ cây dài ra', 'Để cây ngừng lớn', null, 'Để kết quả và tạo ra hạt', null::jsonb, 'Hoa phát triển thành quả, trong quả có hạt. Hạt lại mọc thành cây mới.', 'vong_doi_cay'),
    (2::smallint, 'multiple_choice', 'So với nòng nọc mới nở, ếch con có gì khác?', 'Đã có bốn chân', 'Có đuôi dài hơn', 'Không có miệng', 'Có đôi cánh', 'Đã có bốn chân', null::jsonb, 'Nòng nọc mới nở chưa có chân. Khi thành ếch con, nó đã có bốn chân để nhảy.', 'vong_doi_ech'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng với vòng đời của bướm?', 'Trứng → sâu → nhộng → bướm', 'Trứng → nhộng → sâu → bướm', 'Sâu → trứng → nhộng → bướm', 'Nhộng → sâu → trứng → bướm', 'Trứng → sâu → nhộng → bướm', null::jsonb, 'Trứng nở ra sâu, sâu làm kén hóa nhộng, nhộng biến thành bướm.', 'vong_doi_buom'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng với vòng đời của ếch?', 'Trứng → nòng nọc → ếch con → ếch trưởng thành', 'Nòng nọc → trứng → ếch con → ếch trưởng thành', 'Trứng → ếch con → nòng nọc → ếch trưởng thành', null, 'Trứng → nòng nọc → ếch con → ếch trưởng thành', null::jsonb, 'Trứng ếch nở ra nòng nọc, nòng nọc mọc chân thành ếch con, rồi lớn thành ếch trưởng thành.', 'vong_doi_ech'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng với vòng đời của cây?', 'Hạt nảy mầm → cây con → cây trưởng thành → ra hoa → kết quả', 'Hạt nảy mầm → ra hoa → cây con → kết quả → cây trưởng thành', 'Cây con → hạt nảy mầm → kết quả → ra hoa → cây trưởng thành', null, 'Hạt nảy mầm → cây con → cây trưởng thành → ra hoa → kết quả', null::jsonb, 'Hạt nảy mầm thành cây con, cây lớn lên, ra hoa rồi kết quả. Trong quả lại có hạt.', 'vong_doi_cay'),
    (3::smallint, 'multiple_choice', 'Thứ tự nào đúng với các giai đoạn lớn lên của con người?', 'Em bé → trẻ em → người lớn → người già', 'Trẻ em → em bé → người lớn → người già', 'Em bé → người lớn → trẻ em → người già', 'Người già → người lớn → trẻ em → em bé', 'Em bé → trẻ em → người lớn → người già', null::jsonb, 'Mỗi người đều bắt đầu là em bé, lớn lên thành trẻ em, người lớn rồi về già.', 'vong_doi_nguoi'),
    (3::smallint, 'multiple_choice', 'Điều nào KHÔNG đúng về con muỗi?', 'Muỗi đẻ trứng trên cành cây khô', 'Bọ gậy sống trong nước', 'Bọ gậy lớn lên thành muỗi', 'Đổ nước đọng giúp hạn chế muỗi', 'Muỗi đẻ trứng trên cành cây khô', null::jsonb, 'Muỗi đẻ trứng ở chỗ có nước đọng, không phải trên cành cây khô.', 'vong_doi_muoi'),
    (3::smallint, 'multiple_choice', 'Minh thấy trong chậu nước mưa để lâu ngày có nhiều con nhỏ ngoằn ngoèo bơi lên xuống. Đó là con gì và Minh nên làm gì?', 'Bọ gậy, nên đổ nước đi', 'Nòng nọc, nên nuôi tiếp', 'Sâu non, nên thả thêm lá', 'Cá con, nên cho ăn', 'Bọ gậy, nên đổ nước đi', null::jsonb, 'Đó là bọ gậy, sau vài ngày sẽ thành muỗi. Đổ nước đi để muỗi không sinh sôi.', 'phong_muoi'),
    (3::smallint, 'multiple_choice', 'Điều nào KHÔNG đúng về vòng đời của ếch?', 'Ếch mẹ đẻ ra ếch con giống hệt ếch trưởng thành', 'Nòng nọc sống dưới nước', 'Nòng nọc có đuôi để bơi', 'Nòng nọc lớn lên thành ếch', 'Ếch mẹ đẻ ra ếch con giống hệt ếch trưởng thành', null::jsonb, 'Ếch mẹ đẻ trứng, trứng nở ra nòng nọc có đuôi, không giống ếch trưởng thành.', 'vong_doi_ech')
  ) as v(difficulty, question_type, question_text, option_a, option_b, option_c, option_d, correct_answer, accepted_answers, explanation, skill_tag)
 where l.week_number = 11 and l.lesson_order = 11
   and not exists (select 1 from public.questions q where q.lesson_id = l.id and q.generator_type = 'khoa_hoc');

-- Khoa học • Bài 12: Vật nuôi, cây trồng và động vật hoang dã (25 câu)
insert into public.lessons (subject_id, week_number, lesson_order, name, description, is_published, publish_mode)
select id, 12, 12, 'Vật nuôi, cây trồng và động vật hoang dã', 'Học Vui — Khoa học, bài 12', true, 'week' from public.subjects where code = 'khoa_hoc'
on conflict (subject_id, week_number, lesson_order) do nothing;

insert into public.questions (lesson_id, difficulty, question_type, question_text, option_a, option_b, option_c, option_d,
                              correct_answer, accepted_answers, explanation, skill_tag, source_book, generator_type)
select l.id, v.difficulty, v.question_type, v.question_text, v.option_a, v.option_b, v.option_c, v.option_d,
       v.correct_answer, v.accepted_answers, v.explanation, v.skill_tag, 'Học Vui — Khoa học', 'khoa_hoc'
  from public.lessons l
  join public.subjects s on s.id = l.subject_id and s.code = 'khoa_hoc'
  cross join (values
    (1::smallint, 'multiple_choice', 'Con vật nào thường được nuôi để trông nhà?', 'Con chó', 'Con hổ', 'Con khỉ', 'Con voi', 'Con chó', null::jsonb, 'Chó rất thính tai, thính mũi, thấy người lạ là sủa để báo cho chủ nhà.', 'loi_ich_vat_nuoi'),
    (1::smallint, 'multiple_choice', 'Con vật nào giúp bắt chuột trong nhà?', 'Con mèo', 'Con lợn', 'Con vịt', 'Con trâu', 'Con mèo', null::jsonb, 'Mèo nhanh nhẹn, nhìn rõ trong bóng tối nên bắt chuột rất giỏi.', 'loi_ich_vat_nuoi'),
    (1::smallint, 'multiple_choice', 'Ngày xưa, bác nông dân thường dùng con vật nào để kéo cày?', 'Con trâu', 'Con gà', 'Con mèo', 'Con chó', 'Con trâu', null::jsonb, 'Trâu khỏe mạnh, chịu khó nên giúp bác nông dân kéo cày, kéo bừa trên ruộng.', 'loi_ich_vat_nuoi'),
    (1::smallint, 'multiple_choice', 'Con vật nào là động vật hoang dã?', 'Con hổ', 'Con gà', 'Con lợn', 'Con chó', 'Con hổ', null::jsonb, 'Hổ sống tự do trong rừng, không do con người nuôi, nên là động vật hoang dã.', 'dong_vat_hoang_da'),
    (1::smallint, 'multiple_choice', 'Cây lúa cho ta thứ gì?', 'Hạt gạo để nấu cơm', 'Sữa để uống', 'Trứng để ăn', null, 'Hạt gạo để nấu cơm', null::jsonb, 'Hạt thóc của cây lúa được xay xát thành gạo để nấu cơm.', 'loi_ich_cay_trong'),
    (1::smallint, 'multiple_choice', 'Gà mái nuôi trong nhà cho ta sản phẩm gì?', 'Trứng', 'Sữa', 'Mật ong', null, 'Trứng', null::jsonb, 'Gà mái đẻ trứng. Trứng gà rất bổ, có nhiều chất đạm.', 'loi_ich_vat_nuoi'),
    (1::smallint, 'multiple_choice', 'Thức ăn chính của trâu, bò là gì?', 'Cỏ và rơm', 'Thịt và cá', 'Bánh kẹo', null, 'Cỏ và rơm', null::jsonb, 'Trâu, bò ăn cỏ, rơm và một số loại lá cây.', 'cham_soc_vat_nuoi'),
    (1::smallint, 'multiple_choice', 'Cúc Phương và Cát Tiên là tên của những nơi nào?', 'Vườn quốc gia', 'Bãi biển', 'Nhà máy', 'Chợ lớn', 'Vườn quốc gia', null::jsonb, 'Cúc Phương và Cát Tiên là vườn quốc gia, nơi bảo vệ rừng và các loài động vật hoang dã.', 'vuon_quoc_gia'),
    (1::smallint, 'multiple_choice', 'Con vật nào được nuôi để lấy sữa uống?', 'Con bò', 'Con gà', 'Con vịt', 'Con chó', 'Con bò', null::jsonb, 'Bò sữa cho ta sữa tươi thơm ngon, giúp em mau lớn.', 'loi_ich_vat_nuoi'),
    (1::smallint, 'text', 'Điền từ: Hổ, voi, khỉ, gấu sống trong tự nhiên nên được gọi là động vật ___.', null, null, null, null, 'hoang dã', '["hoang da"]'::jsonb, 'Những con vật sống tự do trong rừng, không do người nuôi gọi là động vật hoang dã.', 'dong_vat_hoang_da'),
    (2::smallint, 'multiple_choice', 'Vì sao cần giữ chuồng trại vật nuôi sạch sẽ?', 'Để vật nuôi khỏe mạnh, ít bệnh', 'Để vật nuôi chạy nhanh hơn', 'Để vật nuôi không cần ăn', null, 'Để vật nuôi khỏe mạnh, ít bệnh', null::jsonb, 'Chuồng bẩn có nhiều vi khuẩn gây bệnh. Chuồng sạch giúp vật nuôi khỏe mạnh.', 'cham_soc_vat_nuoi'),
    (2::smallint, 'multiple_choice', 'Vì sao cần đưa chó, mèo đi tiêm phòng?', 'Để phòng bệnh cho vật nuôi và cho người', 'Để chó, mèo lớn nhanh gấp đôi', 'Để chó, mèo không cần ăn', 'Để lông chó, mèo đổi màu', 'Để phòng bệnh cho vật nuôi và cho người', null::jsonb, 'Tiêm phòng giúp chó, mèo không mắc bệnh nguy hiểm như bệnh dại, bảo vệ cả người trong nhà.', 'cham_soc_vat_nuoi'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm toàn vật nuôi?', 'Trâu, lợn, gà', 'Hổ, gà, chó', 'Voi, khỉ, mèo', 'Gấu, vịt, bò', 'Trâu, lợn, gà', null::jsonb, 'Trâu, lợn, gà do con người nuôi. Hổ, voi, khỉ, gấu là động vật hoang dã.', 'phan_loai_dong_vat'),
    (2::smallint, 'multiple_choice', 'Nhóm nào gồm toàn cây trồng cho ta lương thực?', 'Lúa, ngô, khoai', 'Hoa hồng, hoa cúc, hoa đào', 'Cỏ may, cỏ gà, rêu', null, 'Lúa, ngô, khoai', null::jsonb, 'Lúa, ngô, khoai cho ta gạo, bắp, củ để ăn no hằng ngày, gọi là cây lương thực.', 'loi_ich_cay_trong'),
    (2::smallint, 'multiple_choice', 'Sao la, voọc chà vá chân nâu là những loài động vật như thế nào?', 'Quý hiếm, cần được bảo vệ', 'Vật nuôi trong nhà', 'Có hại, cần tiêu diệt', 'Có rất nhiều, săn bắt thoải mái', 'Quý hiếm, cần được bảo vệ', null::jsonb, 'Sao la và voọc chà vá chân nâu còn rất ít trong tự nhiên, cần được mọi người bảo vệ.', 'dong_vat_quy_hiem'),
    (2::smallint, 'multiple_choice', 'Vì sao không được săn bắt, mua bán động vật hoang dã?', 'Vì chúng sẽ ít dần và có thể mất hẳn', 'Vì chúng có giá quá rẻ', 'Vì chúng không biết ăn', null, 'Vì chúng sẽ ít dần và có thể mất hẳn', null::jsonb, 'Bị săn bắt nhiều, các loài thú rừng ngày càng ít, có loài có thể không còn trên Trái Đất nữa.', 'bao_ve_dong_vat'),
    (2::smallint, 'multiple_choice', 'Vì sao không nên cho thú ở vườn thú ăn bánh kẹo, đồ ăn vặt?', 'Vì có thể làm thú bị ốm', 'Vì thú sẽ lớn quá nhanh', 'Vì thú sẽ không biết đi', 'Vì bánh kẹo làm thú đổi màu lông', 'Vì có thể làm thú bị ốm', null::jsonb, 'Mỗi loài thú có thức ăn riêng do người chăm sóc chuẩn bị; đồ ăn của người có thể làm chúng đau bụng, bị ốm.', 'bao_ve_dong_vat'),
    (2::smallint, 'multiple_choice', 'Người ta trồng cây ăn quả như cam, xoài, chuối để làm gì?', 'Lấy quả ngon, bổ dưỡng để ăn', 'Lấy thịt và trứng', 'Nhờ cây kéo cày', null, 'Lấy quả ngon, bổ dưỡng để ăn', null::jsonb, 'Cây ăn quả cho ta quả ngọt, có nhiều vitamin tốt cho sức khỏe.', 'loi_ich_cay_trong'),
    (3::smallint, 'multiple_choice', 'Đi chơi vườn thú, Nam thấy chú khỉ rất đáng yêu. Nam nên làm gì?', 'Đứng ngoài rào ngắm và nghe lời hướng dẫn', 'Ném bánh kẹo cho khỉ ăn', 'Lấy que chọc cho khỉ kêu', 'Trèo qua rào để bế khỉ', 'Đứng ngoài rào ngắm và nghe lời hướng dẫn', null::jsonb, 'Không trêu chọc, không cho thú ăn bừa. Thức ăn lạ có thể làm thú bị bệnh, còn trêu thú có thể bị cắn.', 'vuon_thu'),
    (3::smallint, 'multiple_choice', 'Việc nào KHÔNG đúng khi chăm sóc vật nuôi?', 'Để vật nuôi nhịn đói nhiều ngày', 'Cho ăn uống đầy đủ', 'Giữ chuồng sạch sẽ', 'Đưa đi tiêm phòng', 'Để vật nuôi nhịn đói nhiều ngày', null::jsonb, 'Vật nuôi cần được cho ăn uống đủ mỗi ngày. Để chúng nhịn đói sẽ làm chúng yếu và ốm.', 'cham_soc_vat_nuoi'),
    (3::smallint, 'multiple_choice', 'Chú Ba thấy có người rao bán một con voọc con bắt từ rừng. Chú nên làm gì?', 'Không mua và báo cho kiểm lâm hoặc công an', 'Mua về nuôi làm cảnh', 'Mua về nhốt chơi', 'Mặc kệ vì không phải việc của mình', 'Không mua và báo cho kiểm lâm hoặc công an', null::jsonb, 'Mua bán động vật hoang dã là sai. Báo cho người có trách nhiệm để voọc được cứu và thả về rừng.', 'bao_ve_dong_vat'),
    (3::smallint, 'multiple_choice', 'Điều nào KHÔNG đúng về động vật hoang dã?', 'Có thể bắt về nhà nuôi tùy thích', 'Sống tự do trong rừng, núi', 'Nhiều loài quý hiếm cần bảo vệ', 'Được bảo vệ ở các vườn quốc gia', 'Có thể bắt về nhà nuôi tùy thích', null::jsonb, 'Động vật hoang dã cần được sống trong tự nhiên. Bắt chúng về nhà là có hại và trái luật.', 'dong_vat_hoang_da'),
    (3::smallint, 'multiple_choice', 'Bé Lan vừa ôm chú chó con xong thì mẹ gọi ăn cơm. Lan nên làm gì trước?', 'Rửa tay sạch bằng xà phòng', 'Ngồi vào ăn ngay', 'Lau tay vào quần áo', 'Thổi phù vào tay', 'Rửa tay sạch bằng xà phòng', null::jsonb, 'Lông và miệng vật nuôi có thể mang vi khuẩn. Rửa tay bằng xà phòng giúp Lan không bị ốm.', 've_sinh_vat_nuoi'),
    (3::smallint, 'multiple_choice', 'Bạn Tú muốn góp phần bảo vệ động vật hoang dã. Việc làm nào phù hợp với Tú?', 'Nhắc mọi người không mua bán thú rừng', 'Bẫy chim rừng về nuôi', 'Mua đồ làm từ ngà voi', 'Phá tổ chim trên cây', 'Nhắc mọi người không mua bán thú rừng', null::jsonb, 'Khi không ai mua bán thú rừng, chúng sẽ không bị săn bắt và được sống yên ổn.', 'bao_ve_dong_vat'),
    (3::smallint, 'multiple_choice', 'Con vật này sống trong rừng Việt Nam, thân phủ đầy vảy cứng, gặp nguy hiểm thì cuộn tròn lại và đang bị săn bắt nhiều. Đó là con gì?', 'Tê tê', 'Con mèo', 'Con voi', 'Con trâu', 'Tê tê', null::jsonb, 'Tê tê có lớp vảy cứng, biết cuộn tròn để tự vệ. Tê tê là loài quý hiếm cần bảo vệ.', 'dong_vat_quy_hiem')
