    (1::smallint, 'multiple_choice', 'Nước lấy từ giếng, từ vòi cần được làm gì trước khi uống?', 'Đun sôi để nguội', 'Cho thêm muối', 'Phơi ngoài nắng', null, 'Đun sôi để nguội', null::jsonb, 'Đun sôi giúp diệt vi khuẩn trong nước, uống vào không bị đau bụng.', 'nuoc_sach'),
    (1::smallint, 'multiple_choice', 'Mưa rơi xuống từ đâu?', 'Từ những đám mây', 'Từ Mặt Trăng', 'Từ đỉnh núi', null, 'Từ những đám mây', null::jsonb, 'Mây gồm rất nhiều giọt nước nhỏ. Khi các giọt to và nặng dần sẽ rơi xuống thành mưa.', 'vong_tuan_hoan_nuoc'),
