    (3::smallint, 'multiple_choice', 'Bạn Thảo cầm cục nước đá trên tay, một lúc sau tay bị ướt. Vì sao?', 'Hơi ấm của tay làm nước đá tan thành nước', 'Tay Thảo đổ rất nhiều mồ hôi', 'Nước đá biến ngay thành hơi nước', null, 'Hơi ấm của tay làm nước đá tan thành nước', null::jsonb, 'Tay ấm hơn nước đá nên đá tan dần, chuyển từ thể rắn sang thể lỏng làm ướt tay.', 'the_cua_nuoc'),
    (3::smallint, 'multiple_choice', 'Việc làm nào KHÔNG tiết kiệm nước?', 'Vừa đánh răng vừa để vòi nước chảy', 'Dùng nước vo gạo để tưới cây', 'Khóa chặt vòi sau khi dùng', 'Báo người lớn sửa vòi bị rò rỉ', 'Vừa đánh răng vừa để vòi nước chảy', null::jsonb, 'Để vòi chảy khi đánh răng làm phí rất nhiều nước. Hãy hứng nước vào cốc rồi khóa vòi.', 'tiet_kiem_nuoc')
