    (2::smallint, 'multiple_choice', 'Điều nào đúng về đá?', 'Có nhiều loại, loại cứng, loại mềm khác nhau', 'Viên đá nào cũng mềm như đất sét', 'Đá chỉ có duy nhất màu đen', null, 'Có nhiều loại, loại cứng, loại mềm khác nhau', null::jsonb, 'Đá có nhiều loại với độ cứng, màu sắc khác nhau. Đá cứng thường dùng để xây dựng.', 'da'),
