    (3::smallint, 'multiple_choice', 'Sáng nay trời nắng to, nhiệt độ cao. Thu chuẩn bị đi học, Thu nên chọn trang phục nào?', 'Mũ rộng vành, áo chống nắng mỏng nhẹ', 'Áo len dày và khăn quàng cổ', 'Áo mưa kín mít', null, 'Mũ rộng vành, áo chống nắng mỏng nhẹ', null::jsonb, 'Trời nắng nóng nên mặc đồ mỏng, mát và che chắn bằng mũ, áo chống nắng.', 'trang_phuc_thoi_tiet'),
    (3::smallint, 'multiple_choice', 'Buổi chiều, trời vừa tạnh mưa thì nắng chiếu ra. Ngọc quay lưng về phía Mặt Trời. Ngọc có thể thấy gì trên bầu trời?', 'Cầu vồng', 'Mưa đá', 'Sương mù', null, 'Cầu vồng', null::jsonb, 'Khi có nắng sau mưa, đứng quay lưng về phía Mặt Trời ta dễ thấy cầu vồng bảy màu.', 'cau_vong'),
    (3::smallint, 'multiple_choice', 'Điều nào KHÔNG đúng về thời tiết?', 'Mây đen kéo đến báo hiệu trời sắp nắng to', 'Sương mù làm ta khó nhìn xa', 'Mưa đá là những cục nước đá rơi từ trên trời', 'Trời lạnh cần mặc áo ấm', 'Mây đen kéo đến báo hiệu trời sắp nắng to', null::jsonb, 'Mây đen kéo đến báo hiệu trời sắp mưa, không phải sắp nắng.', 'hien_tuong_thoi_tiet'),
    (3::smallint, 'multiple_choice', 'Bản tin dự báo nói ngày mai có mưa to. Phúc nên chuẩn bị gì khi đi học?', 'Mang theo áo mưa', 'Mang kem chống nắng và kính râm', 'Mang quạt cầm tay', null, 'Mang theo áo mưa', null::jsonb, 'Nghe dự báo có mưa thì mang áo mưa để không bị ướt và ốm.', 'du_bao_thoi_tiet'),
